from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])

    # The separator color has the highest count in at least one complete row.
    row_peaks = {}
    for row in grid:
        color, count = Counter(row).most_common(1)[0]
        row_peaks[color] = max(row_peaks.get(color, 0), count)
    line = max(row_peaks, key=row_peaks.get)

    row_lines = [
        r for r, row in enumerate(grid)
        if row.count(line) > 0.7 * w
    ]
    col_lines = [
        c for c in range(w)
        if sum(grid[r][c] == line for r in range(h)) > 0.7 * h
    ]

    interior = Counter(
        grid[r][c]
        for r in range(h) for c in range(w)
        if r not in row_lines and c not in col_lines
    )
    fill = interior.most_common(1)[0][0]

    marker_cols = [
        c for c in col_lines
        if any(grid[r][c] != line for r in row_lines)
    ]

    out = []
    for r1, r2 in zip(row_lines, row_lines[1:]):
        row = []
        for c1, c2 in zip(marker_cols, marker_cols[1:]):
            corners = [
                grid[r1][c1], grid[r1][c2],
                grid[r2][c1], grid[r2][c2]
            ]
            row.append(corners[0] if corners[0] != line and len(set(corners)) == 1 else fill)
        out.append(row)

    return out
