from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])

    # Divider color is the most frequent row-wise mode at its strongest row.
    strongest = {}
    for row in grid:
        color, count = Counter(row).most_common(1)[0]
        strongest[color] = max(strongest.get(color, 0), count)
    divider = max(strongest, key=strongest.get)

    row_lines = [r for r in range(h) if grid[r].count(divider) > 0.6 * w]
    col_lines = [
        c for c in range(w)
        if sum(grid[r][c] == divider for r in range(h)) > 0.6 * h
    ]

    interior = Counter(
        grid[r][c]
        for r in range(h) for c in range(w)
        if r not in row_lines and c not in col_lines
    )
    background = interior.most_common(1)[0][0]

    marked = [
        (i, j)
        for i, r in enumerate(row_lines)
        for j, c in enumerate(col_lines)
        if grid[r][c] != divider
    ]
    if not marked:
        return [[background]]

    rmin = min(i for i, _ in marked)
    rmax = max(i for i, _ in marked)
    cmin = min(j for _, j in marked)
    cmax = max(j for _, j in marked)

    result = []
    for i in range(rmin, rmax):
        row = []
        for j in range(cmin, cmax):
            corners = [
                grid[row_lines[i]][col_lines[j]],
                grid[row_lines[i]][col_lines[j + 1]],
                grid[row_lines[i + 1]][col_lines[j]],
                grid[row_lines[i + 1]][col_lines[j + 1]],
            ]
            if corners[0] != divider and all(x == corners[0] for x in corners):
                row.append(corners[0])
            else:
                row.append(background)
        result.append(row)

    return result
